<template>
<div class="admin-console">
 <section v-if="!connected" class="admin-login"><div class="admin-mark">D</div><p class="admin-kicker">운영 관리</p><h1>관리자 로그인</h1><p>가입 심사와 고객 문의를 한곳에서 관리합니다.</p><form @submit.prevent="connect"><label>관리자 키<input v-model="key" type="password" autocomplete="off" required placeholder="X-Admin-Key 입력"/></label><button class="accent" :disabled="loading">{{loading?'확인 중…':'관리자 접속'}}</button></form><p v-if="error" class="error" role="alert">{{error}}</p></section>
 <template v-else>
  <aside class="admin-sidebar"><div class="brand"><b>D</b><div>관리자<span>운영 콘솔</span></div></div><nav aria-label="관리자 메뉴"><RouterLink v-for="n in navigation" :key="n.id" :to="'/admin/'+n.id" :class="{active:section===n.id}"><span>{{n.icon}}</span>{{n.label}}</RouterLink></nav><div class="sidebar-bottom"><a href="/profile">사용자 화면 ↗</a><button @click="logout">관리자 로그아웃</button></div></aside>
  <main class="admin-content"><header class="admin-heading"><div><p class="admin-kicker">운영 관리 / {{heading}}</p><h1>{{heading}}</h1><p>{{descriptions[section]}}</p></div><button class="outlined" :disabled="loading" @click="load">새로고침</button></header>
   <div v-if="error" role="alert" class="error-banner">{{error}}</div><div v-if="notice" role="status" class="success-banner">{{notice}}</div>
   <template v-if="section==='overview'"><div class="metric-grid"><button v-for="c in cards" :key="c.key" @click="router.push(c.to)"><span>{{c.label}}</span><strong>{{summary[c.key]??'—'}}</strong><small>{{c.hint}} ↗</small></button></div><section class="admin-panel"><h2>지금 처리할 업무</h2><div class="work-links"><RouterLink to="/admin/signup"><strong>가입 심사</strong><p>신규 회원의 프로필과 사진을 확인합니다.</p><span>심사 대기 {{summary.signup||0}}명 →</span></RouterLink><RouterLink to="/admin/changes"><strong>프로필 변경 심사</strong><p>기존 승인 내용과 수정 내용을 비교합니다.</p><span>변경 대기 {{summary.changes||0}}명 →</span></RouterLink><RouterLink to="/admin/support"><strong>고객센터 상황실</strong><p>문의에 답변하고 신고·계정 조치를 처리합니다.</p><span>처리 중 문의 {{summary.inquiries||0}}건 →</span></RouterLink></div></section></template>
   <template v-else-if="['members','signup','changes'].includes(section)"><form class="admin-toolbar" @submit.prevent="page=0;load()"><label class="search-field">회원 검색<input v-model="query" placeholder="이메일 또는 닉네임"/></label><label v-if="section!=='changes'">계정 상태<select v-model="status"><option value="ALL">전체</option><option v-for="(v,k) in states" :value="k">{{v}}</option></select></label><label>정렬<select v-model="sort"><option value="NEWEST">최근 가입순</option><option value="OLDEST">오래된 가입순</option><option value="WARNINGS">경고 많은순</option><option value="BLOCKS">차단 많은순</option><option value="SUSPENSION_END">정지 종료일순</option></select></label><button class="accent" :disabled="loading">검색</button><button type="button" @click="status='SUSPENDED';page=0;load()">정지 회원 보기</button><span class="result-count">총 {{total}}명</span></form><section class="admin-panel table-panel"><table><thead><tr><th>회원</th><th>상태</th><th>경고 / 차단</th><th>정지 정보</th><th>프로필 심사</th><th>안전 검토</th><th>가입일</th><th></th></tr></thead><tbody><tr v-for="u in members" :key="u.id"><td><button class="table-name" @click="detail(u.id)">{{u.nickname}}</button><small>#{{u.id}} · {{u.email}}</small></td><td><span class="tag" :class="u.status.toLowerCase()">{{states[u.status]||u.status}}</span><small v-if="u.resting">휴식 중</small></td><td>경고 {{u.warningCount||0}}회<small>누적 차단 {{u.totalBlockCount||0}}회 · 현재 {{u.activeBlockCount||0}}명</small></td><td>{{u.sanctionType==='PERMANENT'?'영구 정지':u.sanctionType==='TEMPORARY'?'기간 정지':u.status==='SUSPENDED'?'관리자 제한':'—'}}<small v-if="u.suspendedUntil">{{date(u.suspendedUntil)}}까지</small></td><td>{{reviewLabel(u.reviewStatus)}}</td><td><span :class="['risk-tag',{warning:u.risk!=='NORMAL'}]">{{riskLabels[u.risk]||u.risk}}</span></td><td>{{date(u.createdAt)}}</td><td><button class="outlined" @click="detail(u.id)">상세 보기</button></td></tr></tbody></table><p v-if="!members.length" class="empty">{{loading?'불러오는 중…':'해당 조건의 회원이 없습니다.'}}</p><footer class="pagination"><button :disabled="loading||page===0" @click="page--;load()">이전</button><span>{{page+1}} / {{Math.max(1,Math.ceil(total/30))}}</span><button :disabled="loading||(page+1)*30>=total" @click="page++;load()">다음</button></footer></section></template>
   <template v-else-if="section==='support'"><div class="admin-tabs"><button v-for="t in supportTabs" :class="{active:tab===t[0]}" @click="tab=t[0];load()">{{t[1]}}</button></div><form class="admin-toolbar" @submit.prevent="load"><label v-if="tab!=='reports'">검색<input v-model="query" placeholder="이메일, 닉네임 또는 내용"/></label><label v-if="tab==='inquiries'||tab==='reports'">처리 상태<select v-model="supportStatus"><option value="OPEN">접수</option><option value="ALL">전체</option><option v-if="tab==='inquiries'" value="IN_PROGRESS">처리 중</option><option value="RESOLVED">처리 완료</option><option v-if="tab==='inquiries'" value="CLOSED">종결</option></select></label><button class="accent" :disabled="loading">조회</button></form>
    <section class="admin-panel table-panel"><table v-if="tab==='inquiries'"><thead><tr><th>문의</th><th>회원</th><th>상태</th><th>접수일</th><th></th></tr></thead><tbody><tr v-for="n in rows" :key="n.id"><td><strong>{{n.category}}</strong><p class="truncate">{{n.question}}</p></td><td><button class="table-name" @click="detail(n.userId)">{{n.nickname}}</button><small>{{n.email}}</small></td><td><span class="tag">{{supportLabels[n.status]||n.status}}</span></td><td>{{date(n.createdAt)}}</td><td><button class="outlined" @click="openCase(n,'inquiry')">답변·처리</button></td></tr></tbody></table>
    <table v-else-if="tab==='reports'"><thead><tr><th>신고 사유</th><th>신고자 → 대상</th><th>상태</th><th>접수일</th><th></th></tr></thead><tbody><tr v-for="n in rows" :key="n.id"><td><strong>{{n.reasonCode}}</strong><p class="truncate">{{n.detail}}</p></td><td>#{{n.reporterUserId}} → <button class="table-name" @click="detail(n.reportedUserId)">#{{n.reportedUserId}}</button></td><td><span class="tag">{{supportLabels[n.status]||n.status}}</span></td><td>{{date(n.createdAt)}}</td><td><button class="outlined" @click="openCase(n,'report')">검토·처리</button></td></tr></tbody></table>
    <table v-else-if="tab==='risk'"><thead><tr><th>회원</th><th>검토 상태</th><th>위험 점수</th><th>최근 참고 사유</th><th></th></tr></thead><tbody><tr v-for="u in rows" :key="u.userId"><td><strong>{{u.nickname}}</strong><small>{{u.email}}</small></td><td>{{riskLabels[u.fraudReviewStatus]}}</td><td>{{u.fraudRiskScore}}</td><td class="truncate">{{u.latestRiskDetail||'—'}}</td><td><button class="outlined" @click="detail(u.userId)">회원 검토</button></td></tr></tbody></table>
    <table v-else><thead><tr><th>신원 구분</th><th>회원</th><th>사유</th><th></th></tr></thead><tbody><tr v-for="n in rows" :key="n.id"><td>{{n.identityType}}</td><td>{{n.userId||n.sourceUserId||'—'}}</td><td>{{n.reason||n.blockReason||'차단된 신원 정보'}}</td><td><button class="outlined" @click="openCase(n,'identity')">차단 해제</button></td></tr></tbody></table><p v-if="!rows.length" class="empty">{{loading?'불러오는 중…':'처리할 항목이 없습니다.'}}</p></section><p v-if="tab==='risk'" class="subtle">위험 점수는 참고 정보입니다. 신고 내용과 회원 정보를 확인한 뒤 조치해 주세요.</p></template>
  </main>
 </template>
 <dialog ref="memberModal" class="admin-dialog member-detail" @cancel="busy&&$event.preventDefault()"><template v-if="selected"><header><div><p class="admin-kicker">회원 #{{selected.member.id}}</p><h2>{{selected.member.nickname}}</h2><p>{{selected.member.email}}</p></div><button class="icon-close" :disabled="busy" @click="memberModal.close()" aria-label="닫기">×</button></header><div class="detail-tags"><span class="tag">{{states[selected.member.status]}}</span><span class="tag">{{reviewLabel(selected.member.reviewStatus)}}</span><span v-if="selected.member.resting" class="tag">휴식 중</span></div><div class="detail-columns"><section><h3>현재 등록 내용 {{selected.approved?'· 심사 대상':''}}</h3><div class="review-photos"><img v-for="p in selected.images" :key="p.id" :src="photo(p.imageUrl)" :alt="p.isMain?'대표사진':'등록 사진'"/></div><dl class="detail-fields"><div><dt>생년월일 / 성별</dt><dd>{{selected.verification?.birthDate}} / {{selected.verification?.gender==='MALE'?'남성':'여성'}}</dd></div><div v-for="[field,label] in profileFields"><dt>{{label}}</dt><dd>{{selected.profile?.[field]||'—'}}</dd></div></dl></section><section v-if="selected.approved"><h3>현재 공개 중인 승인 내용</h3><div class="review-photos"><img v-for="p in selected.approved.images" :src="photo(p)" alt="기존 승인 사진"/></div><strong>{{selected.approved.nickname}}</strong><dl class="detail-fields"><div v-for="[field,label] in profileFields"><dt>{{label}}</dt><dd>{{selected.approved[field]||'—'}}</dd></div></dl></section></div>
 <section class="decision-area" v-if="selected.member.status!=='DELETED'"><h3>{{selected.member.reviewStatus==='PENDING'?'프로필 변경 심사':'회원 관리'}}</h3><label>회원 안내 또는 조치 사유<textarea v-model="decisionNote" maxlength="1000" rows="3" placeholder="반려 사유나 계정 조치 이유를 입력하세요."/></label><div class="decision-buttons"><template v-if="['PENDING_REVIEW','REJECTED'].includes(selected.member.status)"><button class="accent" :disabled="busy" @click="decide('signup-approve')">가입 승인</button><button class="outlined danger" :disabled="busy||!decisionNote.trim()" @click="decide('signup-reject')">가입 반려</button></template><template v-if="selected.member.status==='ACTIVE'&&selected.member.reviewStatus==='PENDING'"><button class="accent" :disabled="busy" @click="decide('change-approve')">변경 승인</button><button class="outlined danger" :disabled="busy||!decisionNote.trim()" @click="decide('change-reject')">보완 요청</button></template></div><details><summary>계정 제한·안전 검토 조치</summary><p class="subtle">입력한 사유는 운영자 메모로 저장됩니다.</p><select v-model="riskAction"><option v-for="[value,label] in riskActions" :value="value">{{label}}</option></select><button class="outlined" :disabled="busy||!decisionNote.trim()" @click="confirmRisk">선택한 조치 적용</button></details></section><section><h3>약관 동의 이력</h3><p v-if="!selected.consents.length" class="subtle">저장된 동의 이력이 없습니다.</p><p v-for="c in selected.consents" class="subtle">{{c.version}} · {{date(c.acceptedAt)}} · 마케팅 {{c.marketing?'동의':'미동의'}}</p><h3>심사 이력</h3><p v-if="!selected.history.length" class="subtle">기록이 없습니다.</p><article v-for="h in selected.history" class="history-row"><b>{{h.actionType}}</b><span>{{date(h.createdAt)}}</span><p>{{h.detail}}</p></article></section></template><p v-if="detailError" class="error" role="alert">{{detailError}}</p></dialog>
 <dialog ref="caseModal" class="admin-dialog case-dialog" @cancel="busy&&$event.preventDefault()"><header><h2>{{caseType==='inquiry'?'고객 문의 처리':caseType==='report'?'신고 처리':caseType==='risk'?'계정 조치 확인':'신원 차단 해제'}}</h2><button class="icon-close" :disabled="busy" @click="caseModal.close()" aria-label="닫기">×</button></header><template v-if="activeCase"><p class="case-body">{{activeCase.question||activeCase.detail||caseDescription}}</p><form @submit.prevent="saveCase"><label v-if="caseType==='inquiry'">처리 상태<select v-model="caseStatus"><option v-for="(v,k) in supportLabels" :value="k">{{v}}</option></select></label><template v-if="caseType==='report'"><label>처리 방안<select v-model="reportAction" :disabled="activeCase.status==='RESOLVED'"><option value="NONE">조치 없음</option><option value="WARNING">경고</option><option value="TEMPORARY">기간 정지</option><option value="PERMANENT">영구 정지</option></select></label><label v-if="reportAction==='TEMPORARY'">정지 일수<input v-model.number="reportDays" type="number" min="1" max="365" required :disabled="activeCase.status==='RESOLVED'"/></label><label v-if="reportAction!=='NONE'">대상 회원에게 안내할 사유<textarea v-model="publicReason" required maxlength="1000" :disabled="activeCase.status==='RESOLVED'"/></label><p v-if="reportAction==='TEMPORARY'||reportAction==='PERMANENT'" class="error">저장 즉시 대상 회원의 로그인·추천·채팅이 제한됩니다. {{reportAction==='PERMANENT'?'영구 정지는 자동 해제되지 않습니다.':'기간 만료 시 기존 계정 상태로 복귀합니다.'}}</p><p v-if="activeCase.status==='RESOLVED'">이미 처리된 신고입니다. {{date(activeCase.resolvedAt)}}</p></template><label v-if="caseType==='inquiry'||caseType==='report'">{{caseType==='inquiry'?'회원에게 보낼 답변':'운영자 처리 메모'}}<textarea v-model="caseNote" maxlength="1000" rows="5" required/></label><p v-if="caseType==='report'" class="subtle">메모는 회원에게 공개되지 않습니다. 신고자에게 처리 결과가, 대상 회원에게 별도로 작성한 안내 사유가 전송됩니다.</p><button class="accent" :disabled="busy||(caseType==='report'&&activeCase.status==='RESOLVED')">{{busy?'처리 중…':caseType==='inquiry'?'답변 저장':caseType==='report'?'신고 처리 완료':'확인 후 적용'}}</button></form></template><p v-if="caseError" class="error" role="alert">{{caseError}}</p></dialog>
</div>
</template>
<script setup>
import {ref,computed,watch,onMounted} from 'vue';import {useRoute,useRouter} from 'vue-router';import api from '../../api/api';
const route=useRoute(),router=useRouter(),key=ref(sessionStorage.getItem('dating-admin-key')||''),connected=ref(false),loading=ref(false),busy=ref(false),error=ref(''),notice=ref(''),summary=ref({}),members=ref([]),rows=ref([]),total=ref(0),page=ref(0),query=ref(''),status=ref('ALL'),sort=ref('NEWEST'),reportAction=ref('NONE'),reportDays=ref(7),publicReason=ref(''),supportStatus=ref('OPEN'),tab=ref('inquiries'),memberModal=ref(),caseModal=ref(),selected=ref(),detailError=ref(''),decisionNote=ref(''),riskAction=ref('MARK_WATCH'),activeCase=ref(),caseType=ref(''),caseNote=ref(''),caseStatus=ref('OPEN'),caseError=ref(''),caseDescription=ref('');let sequence=0;
const section=computed(()=>route.params.section||'overview');const navigation=[{id:'overview',label:'운영 현황',icon:'◫'},{id:'members',label:'회원 목록',icon:'♙'},{id:'signup',label:'가입 심사',icon:'✓'},{id:'changes',label:'프로필 변경 심사',icon:'↻'},{id:'support',label:'고객센터 상황실',icon:'☏'}];const heading=computed(()=>navigation.find(n=>n.id===section.value)?.label||'운영 현황');const descriptions={overview:'접수된 업무와 처리 현황을 확인하세요.',members:'전체 회원을 검색하고 활동 상태를 확인합니다.',signup:'가입 정보와 사진을 확인한 뒤 승인 또는 반려합니다.',changes:'기존 승인 내용과 변경 내용을 비교해 검토합니다.',support:'문의·신고·계정 검토를 한곳에서 처리합니다.'};
const states={PENDING_REVIEW:'가입 심사 중',ACTIVE:'활동 중',REJECTED:'가입 반려',SUSPENDED:'이용 제한',DELETED:'탈퇴'},riskLabels={NORMAL:'정상',WATCH:'관찰 필요',HIGH_RISK:'집중 검토'},supportLabels={OPEN:'접수',IN_PROGRESS:'처리 중',RESOLVED:'처리 완료',CLOSED:'종결'};const supportTabs=[['inquiries','고객 문의'],['reports','신고 접수'],['risk','안전 검토'],['identities','신원 차단 관리']];const riskActions=[['MARK_NORMAL','정상으로 분류'],['MARK_WATCH','관찰 대상으로 분류'],['SUSPEND_ACCOUNT','계정 이용 제한'],['RELEASE_ACCOUNT','이용 제한 해제'],['BLOCK_IDENTITY','계정 및 신원 차단'],['UNBLOCK_IDENTITY','신원 차단 해제']];const profileFields=[['region','지역'],['job','직업'],['mbti','MBTI'],['introduction','자기소개'],['personality','성격'],['idealType','이상형']];const cards=[{key:'members',label:'전체 회원',hint:'회원 목록',to:'/admin/members'},{key:'signup',label:'가입 심사 대기',hint:'가입 심사',to:'/admin/signup'},{key:'changes',label:'프로필 변경 대기',hint:'변경 심사',to:'/admin/changes'},{key:'inquiries',label:'처리할 고객 문의',hint:'고객센터 상황실',to:'/admin/support'},{key:'reports',label:'미처리 신고',hint:'신고 검토',to:'/admin/support?tab=reports'},{key:'withdrawn',label:'탈퇴 계정',hint:'회원 현황',to:'/admin/members?status=DELETED'}];
const date=v=>v?new Date(v).toLocaleString('ko-KR'):'—',photo=p=>new URL(p,api.defaults.baseURL).href,reviewLabel=s=>s==='PENDING'?'변경 심사 중':s==='REJECTED'?'보완 요청':'승인됨';const headers=()=>({'X-Admin-Key':key.value});const get=(url,params={})=>api.get(url,{headers:headers(),params,timeout:10000});
async function connect(){
 if(loading.value)return;
 key.value=key.value.trim();error.value='';
 if(!key.value||!/^[\x21-\x7E]+$/.test(key.value)){error.value='관리자 키에는 영문·숫자·기호만 입력해 주세요. X-Admin-Key라는 항목 이름은 제외하고 키 값만 입력합니다.';return;}
 loading.value=true;
 try{
  const res=await get('/admin/console/summary');
  if(!res.data||typeof res.data.members!=='number')throw new Error('INVALID_ADMIN_RESPONSE');
  summary.value=res.data;sessionStorage.setItem('dating-admin-key',key.value);connected.value=true;await load();
 }catch(e){
  const status=e.response?.status;
  error.value=status===401||status===403?'관리자 키가 올바르지 않습니다. 키 값을 확인해 주세요.':status===404?'현재 서버에 관리자 기능이 없습니다. 최신 백엔드로 다시 실행해 주세요.':status===502||status===503||status===504?'백엔드 서버(8082)가 응답하지 않습니다. 서버 실행 상태를 확인해 주세요.':status>=500?`서버 처리 오류가 발생했습니다. (HTTP ${status})`:status?`관리자 요청을 처리하지 못했습니다. (HTTP ${status})`:e.message==='INVALID_ADMIN_RESPONSE'?'관리자 API 응답이 올바르지 않습니다. 프론트엔드를 다시 실행해 주세요.':'서버에 연결하지 못했습니다. 페이지를 새로고침하고 백엔드 서버(8082) 실행 상태를 확인해 주세요.';
 }finally{loading.value=false;}
}
function logout(){connected.value=false;key.value='';selected.value=null;members.value=[];rows.value=[];sessionStorage.removeItem('dating-admin-key');}
async function load(){if(!connected.value)return;const request=++sequence;loading.value=true;error.value='';try{if(section.value==='overview'){const res=await get('/admin/console/summary');if(request===sequence)summary.value=res.data;}else if(section.value==='support'){const path=tab.value==='inquiries'?'/admin/support/inquiries':tab.value==='reports'?'/admin/safety/reports':tab.value==='risk'?'/admin/safety/users':'/admin/safety/blocked-identities';const res=await get(path,{status:supportStatus.value,q:query.value,riskStatus:'ALL'});if(request===sequence)rows.value=res.data;}else{const res=await get('/admin/console/members',{q:query.value,status:section.value==='changes'?'ACTIVE':status.value,review:section.value==='changes'?'PENDING':'ALL',page:page.value,sort:sort.value});if(request===sequence){members.value=res.data.items;total.value=res.data.total;}}}catch(e){if(request===sequence)error.value=e.response?.data?.message||'목록을 불러오지 못했습니다.';}finally{if(request===sequence)loading.value=false;}}
function reset(){page.value=0;query.value='';status.value=section.value==='signup'?'PENDING_REVIEW':route.query.status||'ALL';supportStatus.value='OPEN';tab.value=route.query.tab||'inquiries';notice.value='';load();}watch(()=>route.fullPath,reset);onMounted(()=>{reset();if(key.value)connect();});
async function detail(id){detailError.value='';decisionNote.value='';try{selected.value=(await get(`/admin/console/members/${id}`)).data;if(!memberModal.value.open)memberModal.value.showModal();}catch{error.value='회원 상세를 불러오지 못했습니다.';}}
async function decide(action){if(busy.value)return;busy.value=true;detailError.value='';try{const id=selected.value.member.id;if(action.startsWith('change'))await api.post(`/admin/console/members/${id}/review`,{revision:selected.value.member.revision,approve:action.endsWith('approve'),note:decisionNote.value.trim()||(action.endsWith('approve')?'프로필 변경이 승인되었습니다.':'프로필을 보완해 주세요.')},{headers:headers()});else await api.post(`/admin/reviews/${id}/${action.endsWith('approve')?'approve':'reject'}`,{reviewComment:decisionNote.value},{headers:headers()});notice.value='심사 결과를 저장했습니다.';await detail(id);await load();}catch(e){detailError.value=e.response?.data?.message||'심사를 처리하지 못했습니다.';}finally{busy.value=false;}}
function openCase(n,type){activeCase.value=n;caseType.value=type;caseNote.value=n.adminReply||n.adminNote||'';caseStatus.value=n.status||'OPEN';reportAction.value=n.resolutionAction||'NONE';reportDays.value=n.suspensionDays||7;publicReason.value=n.publicReason||'';caseDescription.value=type==='identity'?'이 신원의 차단을 해제할까요?':'';caseError.value='';caseModal.value.showModal();}
function confirmRisk(){activeCase.value=selected.value.member;caseType.value='risk';caseError.value='';caseDescription.value=`${selected.value.member.nickname} 회원에게 ‘${riskActions.find(a=>a[0]===riskAction.value)?.[1]}’ 조치를 적용합니다. 사유: ${decisionNote.value}`;caseModal.value.showModal();}
async function saveCase(){if(busy.value)return;busy.value=true;caseError.value='';try{const id=activeCase.value.id;if(caseType.value==='inquiry')await api.put(`/admin/support/inquiries/${id}`,{status:caseStatus.value,adminReply:caseNote.value},{headers:headers()});else if(caseType.value==='report')await api.put(`/admin/safety/reports/${id}/resolve`,{adminNote:caseNote.value,action:reportAction.value,days:reportDays.value,publicReason:publicReason.value},{headers:headers()});else if(caseType.value==='identity')await api.put(`/admin/safety/blocked-identities/${id}/release`,{},{headers:headers()});else{await api.put(`/admin/safety/users/${id}/review`,{action:riskAction.value,adminNote:decisionNote.value},{headers:headers()});await detail(id);}caseModal.value.close();notice.value='처리 내용을 저장했습니다.';await load();}catch(e){caseError.value=e.response?.data?.message||'처리하지 못했습니다.';}finally{busy.value=false;}}
</script>
